import React from 'react';

export function Alert({ message, tone = 'info' }: { message: string; tone?: 'success' | 'error' | 'info' | 'warning' }) {
  const color = tone === 'success' ? '{{token:colors.accent.success}}' : tone === 'error' ? '{{token:colors.accent.danger}}' : tone === 'warning' ? '{{token:colors.accent.warning}}' : '{{token:colors.accent.primary}}';
  return (
    <div role="alert" style={{ border: `1px solid ${color}`, borderLeft: `4px solid ${color}`, borderRadius: '{{token:spacing.card.borderRadius}}', padding: '{{token:spacing.card.padding}}', background: '{{token:colors.base.surface}}', color: '{{token:colors.text.primary}}', fontSize: '{{token:typography.scale.sm}}' }}>
      {message}
    </div>
  );
}

dismissible.template:
import React from 'react';

export function Alert({ message }: { message: string }) {
  const [hidden, setHidden] = React.useState(false);
  if (hidden) return null;
  return (
    <div role="alert" style={{ display: 'flex', justifyContent: 'space-between', border: '1px solid {{token:colors.accent.primary}}', borderRadius: '{{token:spacing.card.borderRadius}}', padding: '{{token:spacing.card.padding}}' }}>
      <span>{message}</span>
      <button aria-label="dismiss" onClick={() => setHidden(true)} style={{ border: 'none', background: 'none', cursor: 'pointer', color: '{{token:colors.text.secondary}}' }}>×</button>
    </div>
  );
}
